//! Regression tests for server-certificate verification on the TLS path the
//! app uses: `reqwest::Client::builder()` with the process-wide ring provider,
//! which on Linux verifies through rustls-platform-verifier and rustls-webpki.
//! Only built where the platform verifier uses rustls-webpki; macOS and
//! Windows delegate to the OS verifier instead.
//!
//! Fixtures live in `src/testdata/tls/` and are regenerated by `generate.sh`.

use std::io::{Read, Write};
use std::net::TcpListener;
use std::sync::Arc;
use std::time::Duration;

use rustls::pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer};
use rustls::server::{ClientHello, ResolvesServerCert};
use rustls::sign::CertifiedKey;

const TEST_ROOT: &[u8] = include_bytes!("testdata/tls/root.der");
const SERVER_KEY: &[u8] = include_bytes!("testdata/tls/leaf.key.der");
/// Valid leaf for 127.0.0.1 issued by the test root.
const LEAF: &[u8] = include_bytes!("testdata/tls/leaf.der");
/// Leaf for 127.0.0.1 issued by the test root whose public key is a
/// compromised eMudhra intermediate CA key.
const EMUDHRA_KEY_LEAF: &[u8] = include_bytes!("testdata/tls/emudhra-key-leaf.der");
/// SPKI contents copied verbatim from rustls-webpki's distrusted key list.
const EMUDHRA_SPKI: &[u8] = include_bytes!("testdata/tls/EMOVTLSCAG3B.spki.der");

#[derive(Debug)]
struct FixedCert(Arc<CertifiedKey>);

impl ResolvesServerCert for FixedCert {
    fn resolve(&self, _: ClientHello<'_>) -> Option<Arc<CertifiedKey>> {
        Some(self.0.clone())
    }
}

/// Serves a single HTTPS request on 127.0.0.1, presenting `leaf`, and returns
/// the URL to request.
fn serve_once(leaf: &'static [u8]) -> String {
    crate::init_crypto();
    let provider = rustls::crypto::CryptoProvider::get_default().unwrap();
    let key = provider
        .key_provider
        .load_private_key(PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(SERVER_KEY)))
        .unwrap();
    // CertifiedKey::new does not check that the key matches the certificate,
    // so the server can present a certificate for a key it does not hold.
    let cert = Arc::new(CertifiedKey::new(vec![CertificateDer::from(leaf)], key));
    let config = Arc::new(
        rustls::ServerConfig::builder()
            .with_no_client_auth()
            .with_cert_resolver(Arc::new(FixedCert(cert))),
    );

    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let url = format!("https://{}/", listener.local_addr().unwrap());
    std::thread::spawn(move || {
        let Ok((sock, _)) = listener.accept() else {
            return;
        };
        let conn = rustls::ServerConnection::new(config).unwrap();
        let mut tls = rustls::StreamOwned::new(conn, sock);
        let mut request = Vec::new();
        let mut buf = [0u8; 1024];
        while !request.windows(4).any(|w| w == b"\r\n\r\n") {
            match tls.read(&mut buf) {
                // The client aborted the handshake.
                Ok(0) | Err(_) => return,
                Ok(n) => request.extend_from_slice(&buf[..n]),
            }
        }
        let _ =
            tls.write_all(b"HTTP/1.1 200 OK\r\ncontent-length: 2\r\nconnection: close\r\n\r\nok");
        tls.conn.send_close_notify();
        let _ = tls.flush();
    });
    url
}

/// Builds the client the way the app does, with the test root merged into
/// the platform verifier's roots (the same verifier, not a custom one).
fn app_client() -> reqwest::Client {
    crate::init_crypto();
    reqwest::Client::builder()
        .timeout(Duration::from_secs(10))
        // Keep the request local even if an HTTPS proxy is configured.
        .no_proxy()
        .tls_certs_merge([reqwest::Certificate::from_der(TEST_ROOT).unwrap()])
        .build()
        .unwrap()
}

/// Finds the rustls error behind a failed request.
fn rustls_error<'a>(mut err: &'a (dyn std::error::Error + 'static)) -> Option<&'a rustls::Error> {
    loop {
        if let Some(tls) = err.downcast_ref::<rustls::Error>() {
            return Some(tls);
        }
        // io::Error::source() skips the error it wraps, so unwrap it directly.
        err = match err.downcast_ref::<std::io::Error>() {
            Some(io) => io.get_ref()?,
            None => err.source()?,
        };
    }
}

#[tokio::test]
async fn test_tls_valid_chain_is_accepted() {
    let resp = app_client()
        .get(serve_once(LEAF))
        .send()
        .await
        .expect("valid chain should verify");
    assert_eq!(resp.text().await.unwrap(), "ok");
}

#[tokio::test]
async fn test_tls_chain_with_compromised_emudhra_key_is_rejected() {
    assert!(
        EMUDHRA_KEY_LEAF
            .windows(EMUDHRA_SPKI.len())
            .any(|w| w == EMUDHRA_SPKI),
        "fixture must carry the distrusted eMudhra key"
    );

    let err = app_client()
        .get(serve_once(EMUDHRA_KEY_LEAF))
        .send()
        .await
        .expect_err("chain with a distrusted key must not verify");

    // Path building must reject the key itself. Without the distrust list the
    // chain verifies and the handshake only fails later, at the signature
    // check, because the server does not hold the eMudhra private key.
    match rustls_error(&err) {
        Some(rustls::Error::InvalidCertificate(rustls::CertificateError::Other(e)))
            if e.to_string() == "CertDistrusted" => {}
        other => panic!("expected CertDistrusted, got {other:?} ({err:?})"),
    }
}
